def nest_nest_parens(nested_string: str) -> int:
    """ Calculates how deeply nested a set of parentheses is.
    E.g. '(())()' has maximum three levels of nesting while '((()))' has two.

    >>> nest_nest_parens('(())()')
    3
    """
    if '(' not in nested_string or ')' not in nested_string:
        return 0
    count_left = 0
    count_right = 0
    if nested_string[0] == '(':
        count_left += 1
    if nested_string[-1] == ')':
        count_right += 1
    for letter in nested_string:
        if letter == '(':
            count_left += 1
        else:
            count_right += 1
        if abs(count_left - count_right) >= 2:
            return -1
    if abs(count_left - count_right) == 1:
        return max(count_left, count_right)
    return max(count_left, count_right)

