def filter_by_substrings(strings: List[str], substrings: List[str]) -> List[str]:
    """ Filter an input list of strings by given substring(s)
    >>> filter_by_substrings(['abc', 'bacd', 'cde', 'array'], ['a', 'd'])
    ['abc', 'bacd', 'array']
    """
    filtered: List[str] = []
    for substr in substrings:
        filtered += filter_by_substring(strings, substr)
    return filtered


