def get_max_level_of_nesting(paren_group: str) -> int:
    """ Return the maximum nesting of parentheses for given group string representation.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.
    """
    stack = []
    for index, char in enumerate(paren_group):
        if char == '(':
            stack.append(index)
        elif char == ')':
            if len(stack) == 0:
                raise Exception(f'Did not find matching '(' for char {char} for group {paren_group}')
            left_brace_idx = stack.pop()
            paren_group = paren_group[:left_brace_idx] + ')' + paren_group[left_brace_idx + 1:]

    return len(stack)


